import { NextRequest, NextResponse } from 'next/server'
import { PDFDocument, rgb, StandardFonts } from 'pdf-lib'

export const runtime = 'nodejs'

// PDF de Arca como plantilla base64
const TEMPLATE_B64 = ''

const K    = rgb(0, 0, 0)
const W    = rgb(1, 1, 1)  // blanco para cubrir campos
const BLUE = rgb(0, 0.314, 0.627)
const GRAY2 = rgb(0.3, 0.3, 0.3)

const PH = 842
// Baseline: pdf-lib y = PH - yTop - size
const B = (yTop: number, sz: number) => PH - yTop - sz

function fmt(n: number) {
  return n.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

// Cubrir un área con blanco
function cover(page: any, x: number, yTop: number, w: number, h: number, pad = 2) {
  page.drawRectangle({
    x: x - pad, y: PH - yTop - h - pad,
    width: w + pad * 2, height: h + pad * 2,
    color: W, borderWidth: 0,
  })
}

export async function POST(req: NextRequest) {
  try {
    const { comprobante: c, cuitAseg, dirAseg, razonSocial } = await req.json()

    const nro = String(c.nro_cbte_afip ?? c.numero ?? 0).padStart(8, '0')
    const fecha = (c.fecha || '').split('-').reverse().join('/')
    const vto = c.cae_vencimiento ? c.cae_vencimiento.split('-').reverse().join('/') : ''
    const tipo = c.categoria === 'nc' ? 'NOTA DE CREDITO' : 'FACTURA'

    // Cargar plantilla
    const tmplBytes = Buffer.from(TEMPLATE_B64, 'base64')
    
    const fontR = await (async () => {
      const tmp = await PDFDocument.create()
      return tmp.embedFont(StandardFonts.Helvetica)
    })()

    const copias = ['ORIGINAL', 'DUPLICADO', 'TRIPLICADO']
    const outDoc = await PDFDocument.create()
    const R  = await outDoc.embedFont(StandardFonts.Helvetica)
    const Bd = await outDoc.embedFont(StandardFonts.HelveticaBold)
    const It = await outDoc.embedFont(StandardFonts.HelveticaOblique)

    for (const copia of copias) {
      // Copiar plantilla
      const tmplDoc = await PDFDocument.load(tmplBytes)
      const [tmplPage] = await outDoc.copyPages(tmplDoc, [0])
      outDoc.addPage(tmplPage)
      const p = outDoc.getPage(outDoc.getPageCount() - 1)

      const t = (x: number, yTop: number, s: string, sz: number, bold = false, color = K) =>
        p.drawText(s, { x, y: B(yTop, sz), font: bold ? Bd : R, size: sz, color })

      const tR = (xRight: number, yTop: number, s: string, sz: number, bold = false) => {
        const f = bold ? Bd : R
        p.drawText(s, { x: xRight - f.widthOfTextAtSize(s, sz), y: B(yTop, sz), font: f, size: sz, color: K })
      }

      const tC = (xC: number, yTop: number, s: string, sz: number, bold = false) => {
        const f = bold ? Bd : R
        p.drawText(s, { x: xC - f.widthOfTextAtSize(s, sz)/2, y: B(yTop, sz), font: f, size: sz, color: K })
      }

      // ── COPIA: cubrir "ORIGINAL" y escribir el texto correcto ──
      cover(p, 263.8, 25, 68.4, 14)
      tC(298, 25, copia, 14, true)

      // ── COMP NRO: cubrir "00002693" y escribir el nuevo ──
      // "Punto de Venta: 00003  Comp. Nro: 00002693" — x=341..561.5 y=86 h=10
      cover(p, 341, 86, 221, 10)
      t(341, 86, 'Punto de Venta:  0006', 9, true)
      t(461, 86, `Comp. Nro:  ${nro}`, 9, true)

      // ── FECHA EMISIÓN ──
      // "Fecha de Emisión: 21/07/2026" x=341..478 y=102 h=10
      cover(p, 341, 102, 137, 10)
      t(341, 102, 'Fecha de Emisión:', 9, true)
      t(428, 102, fecha, 9)

      // ── RECEPTOR: CUIT, Razón Social, Domicilio, Condición venta ──
      // Fila 1: y=191 h=8
      cover(p, 21, 191, 542, 8)
      t(21, 191, 'CUIT:', 8, true)
      t(52, 191, (cuitAseg || '').replace(/-/g,''), 8)
      t(222.3, 191, 'Apellido y Nombre / Razón Social:', 8, true)
      t(325.8, 191, (razonSocial || '').slice(0, 52), 8)

      // Fila 2: y=208 h=8
      cover(p, 21, 208, 547, 8)
      t(21, 208, 'Condición frente al IVA:', 8, true)
      t(131, 208, 'IVA Responsable Inscripto', 8)
      t(272.5, 208, 'Domicilio Comercial:', 8, true)
      t(340, 208, (dirAseg || '').slice(0, 38), 8)

      // Fila 3: y=225 h=8
      cover(p, 21, 225, 153, 8)
      t(21, 225, 'Condición de venta:', 8, true)
      t(113, 225, 'Cuenta Corriente', 8)

      // ── ITEMS ──
      // Cubrir toda el área de items: y=295..520 (desde abajo del header hasta totales)
      cover(p, 15, 295, 566, 225, 0)

      let iy = 301  // y_top de la primera fila de datos (exacto de pdfplumber)
      for (const it of (c.items || [])) {
        const net = Math.round((it.p || 0) / 1.21 * 100) / 100
        // Código
        t(19, iy, (it.codigo || '').slice(0, 10), 8)
        // Descripción
        t(57, iy, (it.d || '').slice(0, 55), 8)
        // Cantidad
        tC(256, iy, `${Number(it.c || 1).toFixed(2).replace('.', ',')}`, 8)
        // U. medida
        t(285, iy, 'unidades', 8)
        // Precio Unit.
        tR(385, iy, fmt(net), 8)
        // % Bonif
        tR(414, iy, '0,00', 8)
        // Subtotal
        tR(479, iy, fmt(net * (it.c || 1)), 8)
        // Alícuota IVA
        tC(498, iy, '21%', 8)
        // Subtotal c/IVA
        tR(579, iy, fmt((it.c || 1) * (it.p || 0)), 8)

        iy += 18

        // Referencia
        if (c.siniestro || c.patente || c.vehiculo) {
          const ref = [c.vehiculo, c.patente ? `Pat: ${c.patente}` : null, c.siniestro ? `Sin: ${c.siniestro}` : null].filter(Boolean).join(' · ')
          p.drawText(ref, { x: 57, y: B(iy + 4, 7), font: It, size: 7, color: GRAY2 })
          iy += 10
        }
      }

      // ── NOMBRE ASEGURADO (observaciones) ──
      cover(p, 223.4, 683, 149.2, 10)
      if (c.cliente_nombre) tC(298, 670, c.cliente_nombre.toUpperCase(), 9)

      // ── TOTALES ──
      // Cubrir todos los valores
      cover(p, 187, 533, 388, 130, 1)
      // Importe Otros Tributos arriba
      t(187, 533, 'Importe Otros Tributos: $', 9)
      t(329.5, 533, '0,00', 9)
      // Bloque derecho
      const rows: [string, string, boolean, number][] = [
        ['Importe Neto Gravado: $', fmt(c.neto || 0), true,  553],
        ['IVA 27%: $',              '0,00',           false, 566],
        ['IVA 21%: $',              fmt(c.iva || 0),  false, 579],
        ['IVA 10.5%: $',            '0,00',           false, 592],
        ['IVA 5%: $',               '0,00',           false, 605],
        ['IVA 2.5%: $',             '0,00',           false, 618],
        ['IVA 0%: $',               '0,00',           false, 631],
        ['Importe Otros Tributos: $','0,00',           false, 644],
        ['Importe Total: $',  fmt(c.total || 0),       true,  658],
      ]
      for (const [lbl, val, bold, yRow] of rows) {
        const sz = bold ? 10 : 9
        const f = bold ? Bd : R
        p.drawText(lbl, { x: 498 - f.widthOfTextAtSize(lbl, sz) - 4, y: B(yRow, sz), font: f, size: sz, color: K })
        p.drawText(val, { x: 577 - f.widthOfTextAtSize(val, sz), y: B(yRow, sz), font: f, size: sz, color: K })
      }

      // ── CAE ──
      cover(p, 442.6, 717, 121.2, 10)
      cover(p, 374.4, 731, 161.6, 10)
      if (c.cae_emitido) {
        t(442.6, 717, `CAE N°:  ${c.cae_emitido}`, 10, true)
        t(374.4, 731, `Fecha de Vto. de CAE:  ${vto}`, 10, true)
      }
    }

    const bytes = await outDoc.save()
    return new NextResponse(Buffer.from(bytes), {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="0006-${nro}.pdf"`,
      },
    })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}
